function pcmSamples(file){const b=fs.readFileSync(file);for(let i=12;i+8<=b.length;){const n=b.readUInt32LE(i+4);if(b.toString('ascii',i,i+4)==='data'){const data=b.subarray(i+8,i+8+n);return Array.from({length:data.length/2},(_,j)=>data.readInt16LE(j*2)/32768);}i+=8+n+n%2;}throw Error('SYNTHETIC WAV data missing');}
function tone(samples,frequency,start,seconds=.6){let c=0,s=0;const begin=Math.round(start*48000),end=begin+Math.round(seconds*48000);for(let i=begin;i<end;i++){const phase=2*Math.PI*frequency*i/48000;c+=samples[i]*Math.cos(phase);s+=samples[i]*Math.sin(phase);}return Math.hypot(c,s)/(end-begin);}
