test('the exact actual error gap wins over a stale same-video gap; legacy repeat evidence permits QA-only recheck, never approval',async t=>{const f=await visualRepairFixture(t),result=await renderClone({...f.input,call:f.call,visual_repair:f.ready},f.options),g=storedRepeatFailure(f,result);const saved=recordCloneVisualFailure({...f.input,result,error:g.error},{readGap:()=>{throw Error('must not read an earlier gap')}});assert.equal(saved.gap.sha256,g.ref.sha256);assert.equal(saved.missing[0].code,'MOTION_EXPORTED_REPEAT');const before=f.commands.length,recovered=readCompletedCloneVisualRepair(f.input);assert.equal(recovered.video_sha256,result.video_sha256);assert.equal(recovered.qa_repeat_recheck.contract,MOTION_REPEAT_REVIEW_CONTRACT);assert.equal(recovered.quality_approved,false);assert.equal(f.commands.length,before);const file=path.join(result.output_dir,'content-motion-qa',sha('SYNTHETIC independently confirmed repeat'),'checked-report.json');fs.mkdirSync(path.dirname(file));fs.writeFileSync(file,JSON.stringify({...g.report,repeat_review_contract:MOTION_REPEAT_REVIEW_CONTRACT}));assert.equal(readCompletedCloneVisualRepair(f.input),null);});
for(const kind of ['foreign-script','foreign-project','wrong-code'])test('a current error gap with '+kind+' cannot replace the original failure',async t=>{const f=await visualRepairFixture(t),result=await renderClone({...f.input,call:f.call,visual_repair:f.ready},f.options),g=storedRepeatFailure(f,result),before=readCloneVisualRepair(f.input).reference;if(kind==='foreign-script')g.gap.script_text_sha256=sha('foreign');if(kind==='foreign-project')g.gap.project_sha256=sha('foreign');if(kind==='wrong-code')g.error.code='MOTION_STILL_TOO_LONG';fs.writeFileSync(g.gapFile,JSON.stringify(g.gap));g.error.material_discovery.sha256=sha(fs.readFileSync(g.gapFile));g.error.material_discovery.size_bytes=fs.statSync(g.gapFile).size;assert.throws(()=>recordCloneVisualFailure({...f.input,result,error:g.error}),/KNOWN_GAP_REQUIRED/);assert.deepEqual(readCloneVisualRepair(f.input).reference,before)});
test('new known failed receipts remain excluded even when an earlier ready proof omitted that later failure',async t=>{const f=await visualRepairFixture(t),result=await renderClone({...f.input,call:f.call,visual_repair:f.ready},f.options),g=storedRepeatFailure(f,result);g.gap.missing=[{code:'MOTION_DYNAMIC_COVERAGE_LOW'}];fs.writeFileSync(g.gapFile,JSON.stringify(g.gap));g.error.code='MOTION_DYNAMIC_COVERAGE_LOW';g.error.material_discovery.sha256=sha(fs.readFileSync(g.gapFile));g.error.material_discovery.size_bytes=fs.statSync(g.gapFile).size;recordCloneVisualFailure({...f.input,result,error:g.error});assert.equal(readCompletedCloneVisualRepair(f.input),null)});
test('clone visual repair accepts the existing private-video source scope without changing the owner audio or approval',async t=>{const f=await visualRepairFixture(t,{scope:'private-video'});assert.equal(f.failure.quality_approved,false);assert.equal(f.ready.quality_approved,false);assert.equal(f.request.status,'audio_ready');assert.equal(f.ownerProject.binding.scope,'private-video');assert.equal(f.request.first_review_id,f.failure.binding.first_review_id);assert.equal(f.request.provider_result.audio_sha256,f.failure.binding.audio_sha256);});
for(const scope of ['public-video','publishing','private-audio'])test('clone visual repair refuses an unrelated scope '+scope,async t=>{await assert.rejects(()=>visualRepairFixture(t,{scope}),/CLONE_VISUAL_REPAIR_RECEIPT_CHANGED/);});
